inline bool VerifyBody(::flatbuffers::Verifier &verifier, const void *obj, Body type) {
  switch (type) {
    case Body::NONE: {
      return true;
    }
    case Body::Hello: {
      auto ptr = reinterpret_cast<const rc::proto::v2::Hello *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Body::HelloAck: {
      auto ptr = reinterpret_cast<const rc::proto::v2::HelloAck *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Body::Ping: {
      auto ptr = reinterpret_cast<const rc::proto::v2::Ping *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Body::Pong: {
      auto ptr = reinterpret_cast<const rc::proto::v2::Pong *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Body::MouseEvent: {
      auto ptr = reinterpret_cast<const rc::proto::v2::MouseEvent *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Body::KeyboardEvent: {
      auto ptr = reinterpret_cast<const rc::proto::v2::KeyboardEvent *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Body::ScreenRequest: {
      auto ptr = reinterpret_cast<const rc::proto::v2::ScreenRequest *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case Body::ScreenFrame: {
      auto ptr = reinterpret_cast<const rc::proto::v2::ScreenFrame *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

inline bool VerifyBodyVector(::flatbuffers::Verifier &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<Body> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyBody(
        verifier,  values->Get(i), types->GetEnum<Body>(i))) {
      return false;
    }
  }
  return true;
}

